const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const store={get:(k,d)=>{try{const v=localStorage.getItem('aurora_'+k);return v?JSON.parse(v):d}catch{return d}},set:(k,v)=>localStorage.setItem('aurora_'+k,JSON.stringify(v))};

let _ampmShown=null;
function isDigitalClock(){const c=document.body.dataset.clock;return c==='thin'||c==='outline'||c==='modern'||c==='bold';}
function syncAmpm(){const show=isDigitalClock()&&store.get('timeFormat','12h')==='12h';if(show===_ampmShown)return;_ampmShown=show;const ap=$('#d-ampm');if(ap)ap.style.display=show?'inline':'none';}
function pulseClock(){const c=$('#clock-card');if(!c)return;c.style.animation='none';void c.offsetWidth;c.style.animation='';}
function applyClockSize(){const s=store.get('clockSize',100);const c=$('#clock-card');if(c)c.style.scale=s/100;const v=$('#clock-size-val');if(v)v.textContent=s+'%';const r=$('#set-clock-size');if(r&&+r.value!==s)r.value=s;}
// Clock + greeting + date
function tick(){
  const n=new Date();
  const h=n.getHours(), m=n.getMinutes();
  const degM=m*6, degH=(h%12)*30+m*0.5, degS=n.getSeconds()*6;
  $('#h-minute').style.transform=`rotate(${degM}deg)`;
  $('#h-hour').style.transform=`rotate(${degH}deg)`;
  const hs=$('#h-sec');if(hs)hs.style.transform=`rotate(${degS}deg)`;
  const mH=$('#m-hour'),mM=$('#m-minute'),mS=$('#m-sec');if(mH)mH.style.transform=`rotate(${degH}deg)`;if(mM)mM.style.transform=`rotate(${degM}deg)`;if(mS)mS.style.transform=`rotate(${degS}deg)`;
  const ra=$('#rect-arc');if(ra)ra.style.strokeDashoffset=String(100-(n.getSeconds()/60)*100);
  const greet=h<6?'Good night':h<12?'Good morning':h<17?'Good afternoon':'Good evening';
  const name=store.get('name','');
  const showG=store.get('showGreet',0), showC=store.get('showCustom',0), custom=store.get('customGreet','');
  const gEl=$('#greeting');
  if(!showG){gEl.style.display='none';}
  else{gEl.style.display='';gEl.textContent=(showC&&custom?custom:greet+(name?' '+name.toUpperCase():''));}
  const days=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
  const months=['January','February','March','April','May','June','July','August','September','October','November','December'];
  $('#w-day-name').textContent=days[n.getDay()];
  $('#w-date').textContent=`${months[n.getMonth()]} ${n.getDate()}`;
  const tf=store.get('timeFormat','12h');const dh=$('#d-h'),dm=$('#d-m');if(dh)dh.textContent=tf==='24h'?String(h).padStart(2,'0'):String(h%12||12).padStart(2,'0');if(dm)dm.textContent=String(m).padStart(2,'0');
  const ap=$('#d-ampm');if(ap)ap.textContent=h>=12?'PM':'AM';syncAmpm();
}
setInterval(tick,1000);tick();
(function(){const an=$('#analog');if(!an||an.dataset.ticks)return;an.dataset.ticks='1';for(let i=0;i<12;i++){const q=i%3===0;const d=document.createElement('div');d.className='tick';const s=q?3:2;d.style.width=d.style.height=s+'px';d.style.background=q?'rgba(255,255,255,.85)':'rgba(255,255,255,.35)';d.style.transform=`translate(-50%,-50%) rotate(${i*30}deg) translateY(-88px)`;an.appendChild(d);}})();

// Quotes (Suite categories, day-of-year rotation)
const QUOTES=[["Success comes from having dreams that are bigger than your fears.","BOBBY UNSER"],["The best way out is always through.","ROBERT FROST"],["What we think, we become.","BUDDHA"],["Simplicity is the ultimate sophistication.","LEONARDO DA VINCI"],["Whether you think you can or you think you can't, you're right.","HENRY FORD"],["The only way to do great work is to love what you do.","STEVE JOBS"],["In the middle of difficulty lies opportunity.","ALBERT EINSTEIN"],["It always seems impossible until it's done.","NELSON MANDELA"]];
const QUOTE_CATS={General:QUOTES,Motivation:[QUOTES[0],QUOTES[4],QUOTES[5],QUOTES[7]],Stoicism:[["The impediment to action advances action.","MARCUS AURELIUS"],["We suffer more in imagination than in reality.","SENECA"],["It's not what happens to you, but how you react.","EPICTETUS"],["Waste no more time arguing what a good man should be. Be one.","MARCUS AURELIUS"]],'Bhagavad Gita':[["You have a right to your actions, but never to the fruits of action.","BHAGAVAD GITA"],["The mind is restless and difficult to restrain, but it is subdued by practice.","BHAGAVAD GITA"],["Success comes from having dreams that are bigger than your fears.","BOBBY UNSER"]],Buddhism:[["Peace comes from within. Do not seek it without.","BUDDHA"],["What we think, we become.","BUDDHA"],["Happiness is not something ready made. It comes from your own actions.","DALAI LAMA"]]};
function applyQuote(){const n=new Date();const doy=Math.floor((n-new Date(n.getFullYear(),0,0))/864e5);const pool=QUOTE_CATS[store.get('qcat','General')]||QUOTES;const q=pool[doy%pool.length];$('#quote').textContent=`"${q[0]}"`;$('#quote-author').textContent='— '+q[1];}
applyQuote();

// Modals
const overlay=$('#overlay');
function openModal(id){overlay.classList.remove('hidden');$$('.modal').forEach(m=>{m.classList.add('hidden');m.classList.remove('closing');});const t=$('#'+id);if(t)t.classList.remove('hidden');}
function playClose(m){if(!m||m.classList.contains('hidden'))return;m.classList.add('closing');setTimeout(()=>{m.classList.add('hidden');m.classList.remove('closing');},220);}
function closeAll(){overlay.classList.add('hidden');$$('.modal').forEach(playClose);const s=$('#settings-modal');if(s)playClose(s);}
$$('.widget').forEach(w=>w.onclick=()=>openModal(w.dataset.modal));
