// Tasks (Suite-compatible {id,text,completed})
let tasks=store.get('tasks',[{t:'Read',d:false},{t:'Order',d:false}]);
tasks=tasks.map(t=>({id:String(t.id||(Date.now()+Math.random())),text:t.text??t.t??'',completed:!!(t.completed??t.d),createdAt:t.createdAt||Date.now()}));
function renderTasks(){$('#task-list').innerHTML='';tasks.forEach((t)=>{const li=document.createElement('li');li.className=t.completed?'done':'';li.innerHTML=`<span class="tbox">${t.completed?'✓':''}</span><span class="txt"></span>`;li.querySelector('.txt').textContent=t.text;li.onclick=()=>{t.completed=!t.completed;store.set('tasks',tasks);renderTasks();};$('#task-list').appendChild(li);});const open=tasks.filter(t=>!t.completed).length;$('#tasks-count').textContent=`${open} OPEN`;$('#w-tasks').textContent=open?`${open} pending`:'All done';}
$('#task-add-btn').onclick=()=>{const v=$('#task-input').value.trim();if(!v)return;tasks.push({id:String(Date.now()),text:v,completed:false,createdAt:Date.now()});$('#task-input').value='';store.set('tasks',tasks);renderTasks();};
$('#tasks-clear').onclick=()=>{if(!tasks.some(t=>t.completed))return;tasks=tasks.filter(t=>!t.completed);store.set('tasks',tasks);renderTasks();};
