// Simple timer (single session, H/M/S steppers, default 5:00)
let tm={left:store.get('pomoLeft',300),base:store.get('pomoBase',300),running:false,timer:null};
function saveTm(){store.set('pomoLeft',tm.left);store.set('pomoBase',tm.base);}
function fmtHMS(s){s=Math.max(0,Math.round(s));const h=Math.floor(s/3600),m=Math.floor(s%3600/60),ss=s%60;const mm=String(m).padStart(h?2:2,'0'),qq=String(ss).padStart(2,'0');return h?`${h}:${mm}:${qq}`:`${String(m).padStart(2,'0')}:${qq}`;}
function pomBeep(){try{const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;const C=new AC();[660,660,880].forEach((f,i)=>{const o=C.createOscillator(),g=C.createGain();o.connect(g);g.connect(C.destination);o.frequency.value=f;const t=C.currentTime+i*0.25;g.gain.setValueAtTime(0.15,t);g.gain.exponentialRampToValueAtTime(0.001,t+0.2);o.start(t);o.stop(t+0.2);});setTimeout(()=>C.close(),1200);}catch{}}
function drawTm(){const h=Math.floor(tm.left/3600),m=Math.floor(tm.left%3600/60),s=tm.left%60;$('#t-time').textContent=fmtHMS(tm.left);$('#t-fill').style.width=(tm.base?tm.left/tm.base*100:0)+'%';$('#t-play').textContent=tm.running?'⏸':'▶';$('#t-h').textContent=h;$('#t-m').textContent=m;$('#t-s').textContent=s;$('#w-focus').textContent=tm.running?'Focusing… '+fmtHMS(tm.left):(tm.left>0&&tm.left!==tm.base?'Paused':'Ready to focus?');}
function stopTm(){clearInterval(tm.timer);tm.timer=null;tm.running=false;}
function stepTm(unit,d){stopTm();const p={h:Math.floor(tm.left/3600),m:Math.floor(tm.left%3600/60),s:tm.left%60};p[unit]=Math.min(99,Math.max(0,p[unit]+d));tm.left=tm.base=p.h*3600+p.m*60+p.s;saveTm();drawTm();}
$('#t-play').onclick=()=>{if(tm.running){stopTm();}else{if(tm.left<=0)tm.left=tm.base||300;tm.timer=setInterval(()=>{tm.left--;if(tm.left<=0){tm.left=0;stopTm();pomBeep();}saveTm();drawTm();},1000);tm.running=true;}drawTm();};
$('#t-reset').onclick=()=>{stopTm();tm.left=tm.base;saveTm();drawTm();};
$('#t-plus5').onclick=()=>{const cap=99*3600+59*60+59;tm.left=Math.min(cap,tm.left+300);tm.base=Math.min(cap,tm.base+300);saveTm();drawTm();};
$$('.t-stepbtn').forEach(b=>b.onclick=()=>stepTm(b.dataset.u,+b.dataset.d));
drawTm();

// GitHub live (Suite: public events, compare-enriched pushes, 12-week heatmap)
let ghUser=store.get('gh','gauravspam');
const ghCompareCache=new Map();
function ghBranch(ref){return (ref||'').replace(/^refs\/heads\//,'')||'main';}
function ghDayKey(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
async function ghCompare(repo,before,head){const k=`${repo}@${before}...${head}`;if(ghCompareCache.has(k))return ghCompareCache.get(k);try{const r=await fetch(`https://api.github.com/repos/${repo}/compare/${before}...${head}`,{headers:ghHeaders()});const j=r.ok?await r.json():null;ghCompareCache.set(k,j);if(ghCompareCache.size>60)ghCompareCache.delete(ghCompareCache.keys().next().value);return j;}catch{return null;}}
function ghCommitUrl(user,repo,sha){return (/^[0-9a-f]{7,}$/i.test(sha||''))?`https://github.com/${repo}/commit/${sha}`:`https://github.com/${repo}/commits`;}
async function loadGH(){const u=(ghUser||'').trim();const err=$('#gh-err');if(err){err.classList.add('hidden');err.textContent='';}const ul0=$('#gh-commits');if(!u){if(ul0)ul0.innerHTML='<li style="text-align:center;font-size:12px;opacity:.6">Enter your username to see live activity</li>';$('#w-github').textContent='All Caught Up';return;}try{if(ul0)ul0.innerHTML='<div class="gh-skel"></div><div class="gh-skel"></div><div class="gh-skel"></div>';let ev=null;const gc=store.get('ghCache',null);if(gc&&gc.user===u&&(Date.now()-gc.ts)<600000){ev=gc.ev;}else{const r=await fetch(`https://api.github.com/users/${encodeURIComponent(u)}/events/public?per_page=30`,{headers:ghHeaders()});if(r.status===404)throw new Error('User not found');if(r.status===403)throw new Error('Rate limited — add a token in Settings → GitHub, or try again later');if(!r.ok)throw new Error('GitHub request failed');ev=await r.json();try{store.set('ghCache',{user:u,ts:Date.now(),ev});}catch{}}const pushes=ev.filter(e=>e.type==='PushEvent').slice(0,6);const enriched=[];for(const p of pushes){const commits=(p.payload&&p.payload.commits)||[];if(commits.length){commits.forEach(c=>enriched.push({repo:p.repo.name,msg:(c.message||'').split('\n')[0]||'Push',sha:c.sha||'',date:p.created_at}));}else{const n=(p.payload&&p.payload.size)||0;const b=p.payload&&p.payload.before,hd=p.payload&&p.payload.head;if(b&&hd&&!/^0+$/.test(b)){const cmp=await ghCompare(p.repo.name,b,hd);(cmp&&cmp.commits||[]).forEach(c=>enriched.push({repo:p.repo.name,msg:((c.commit&&c.commit.message)||'').split('\n')[0]||'Push',sha:c.sha||'',date:p.created_at}));if(!(cmp&&cmp.commits&&cmp.commits.length))enriched.push({repo:p.repo.name,msg:`Pushed ${n} commit${n===1?'':'s'} to ${ghBranch(p.payload.ref)}`,sha:'',date:p.created_at});}else if(n){enriched.push({repo:p.repo.name,msg:`Pushed ${n} commit${n===1?'':'s'} to ${ghBranch(p.payload&&p.payload.ref)}`,sha:'',date:p.created_at});}}}enriched.sort((a,b)=>new Date(b.date)-new Date(a.date));const repos=new Set(enriched.map(e=>e.repo)).size;$('#gh-total').textContent=enriched.length;$('#gh-streak').textContent=pushes.length;$('#gh-week').textContent=repos;const ul=$('#gh-commits');ul.innerHTML='';enriched.slice(0,8).forEach(e=>{const li=document.createElement('li');const a=document.createElement('a');a.href=ghCommitUrl(u,e.repo,e.sha);a.target='_blank';a.rel='noopener';const ic=document.createElement('span');ic.className='c-ico';ic.textContent='⤺';const dt=document.createElement('span');dt.className='c-date';dt.textContent=new Date(e.date).toLocaleDateString('en-GB',{day:'2-digit',month:'2-digit'});const tx=document.createElement('span');tx.style.cssText='flex:1;min-width:0';const m=document.createElement('div');m.className='c-msg';m.textContent=e.msg||'(no message)';const rp=document.createElement('div');rp.className='c-repo';rp.textContent=e.repo;tx.appendChild(m);tx.appendChild(rp);a.appendChild(ic);a.appendChild(dt);a.appendChild(tx);li.appendChild(a);ul.appendChild(li);});if(!enriched.length)ul.innerHTML='<li style="text-align:center;font-size:12px;opacity:.6">No pushes in the last 90 days</li>';$('#gh-updated').textContent='· updated '+new Date().toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'});$('#w-github').textContent='@'+u;await loadGhRepos();renderGhLangs();loadGhLife();await loadGhBranches();await loadGhRepoCommits();loadGhReadme();applyGhShow();}catch(e){if(err){err.textContent=String((e&&e.message)||e);err.classList.remove('hidden');}$('#w-github').textContent='All Caught Up';}}
function ghSyncInputs(){$('#gh-user-input').value=ghUser;const s=$('#gh-input');if(s)s.value=ghUser;}
ghSyncInputs();loadGH();
let ghSel=store.get('ghSel',{repo:'',branch:'',defBranch:''});
let ghReposCache=[];
function hideCsel(){$$('.cdrop').forEach(d=>d.classList.remove('open'));}
function positionCsel(btn,drop){const r=btn.getBoundingClientRect();drop.style.left=r.left+'px';drop.style.top=(r.bottom+6)+'px';drop.style.width=Math.max(r.width,180)+'px';}
function cselBuild(btnId,items,cur,onPick){const btn=$('#'+btnId),drop=$('#'+btnId.replace('-btn','-drop'));if(!btn||!drop)return;btn.innerHTML='';const nm=document.createElement('span');const found=items.find(i=>i.value===cur);nm.textContent=found?found.label:'Select…';const ch=document.createElement('small');ch.textContent='▾';btn.appendChild(nm);btn.appendChild(ch);drop.innerHTML='';items.forEach(it=>{const li=document.createElement('li');li.textContent=it.label;li.title=it.value;if(it.value===cur)li.classList.add('on');li.onclick=e=>{e.stopPropagation();hideCsel();onPick(it.value);};drop.appendChild(li);});btn.onclick=e=>{e.stopPropagation();const was=drop.classList.contains('open');hideCsel();if(!was){positionCsel(btn,drop);drop.classList.add('open');}};}
async function loadGhRepos(){try{const r=await fetch(`https://api.github.com/users/${encodeURIComponent(ghUser)}/repos?per_page=100&sort=updated`,{headers:ghHeaders()});const j=r.ok?await r.json():[];ghReposCache=j;if(!j.some(x=>x.full_name===ghSel.repo)){ghSel.repo=(j[0]&&j[0].full_name)||'';ghSel.defBranch=(j[0]&&j[0].default_branch)||'main';}else{const cur=j.find(x=>x.full_name===ghSel.repo);if(cur)ghSel.defBranch=cur.default_branch||'main';}store.set('ghSel',ghSel);paintGhRepo();}catch{paintGhRepo();}}
function paintGhRepo(){cselBuild('gh-repo-btn',ghReposCache.map(x=>({value:x.full_name,label:x.name})),ghSel.repo,v=>{ghSel.repo=v;ghSel.branch='';store.set('ghSel',ghSel);paintGhRepo();loadGhBranches().then(()=>{renderGhLangs();loadGhRepoCommits();loadGhReadme();});});}
async function loadGhBranches(){try{paintGhBranch([]);if(!ghSel.repo)return;const r=await fetch(`https://api.github.com/repos/${ghSel.repo}/branches?per_page=100`,{headers:ghHeaders()});const j=r.ok?await r.json():[];if(!j.some(x=>x.name===ghSel.branch))ghSel.branch=ghSel.defBranch||((j[0]&&j[0].name)||'');store.set('ghSel',ghSel);paintGhBranch(j.map(x=>x.name));}catch{paintGhBranch([]);}}
function paintGhBranch(names){cselBuild('gh-branch-btn',names.map(n=>({value:n,label:n})),ghSel.branch,v=>{ghSel.branch=v;store.set('ghSel',ghSel);paintGhBranch(names);loadGhRepoCommits();});}
async function loadGhRepoCommits(){const ul=$('#gh-commits');if(!ul||!ghSel.repo)return;ul.innerHTML='<div class="gh-skel"></div><div class="gh-skel"></div>';try{const r=await fetch(`https://api.github.com/repos/${ghSel.repo}/commits?sha=${encodeURIComponent(ghSel.branch)}&per_page=4`,{headers:ghHeaders()});if(!r.ok)throw 0;const j=await r.json();ul.innerHTML='';if(!j.length)ul.innerHTML='<li style="text-align:center;font-size:12px;opacity:.6">No commits on this branch</li>';j.forEach(c=>{const li=document.createElement('li');const a=document.createElement('a');a.href=(c.html_url)||`https://github.com/${ghSel.repo}/commits`;a.target='_blank';a.rel='noopener';const ic=document.createElement('span');ic.className='c-ico';ic.textContent='⤺';const dt=document.createElement('span');dt.className='c-date';try{dt.textContent=new Date(c.commit.author.date).toLocaleDateString('en-GB',{day:'2-digit',month:'2-digit'});}catch{dt.textContent='';}const tx=document.createElement('span');tx.style.cssText='flex:1;min-width:0';const m=document.createElement('div');m.className='c-msg';m.textContent=((c.commit&&c.commit.message)||'(no message)').split('\n')[0];const rp=document.createElement('div');rp.className='c-repo';rp.textContent=(c.commit&&c.commit.author&&c.commit.author.name)||ghSel.repo;tx.appendChild(m);tx.appendChild(rp);a.appendChild(ic);a.appendChild(dt);a.appendChild(tx);li.appendChild(a);ul.appendChild(li);});const up2=$('#gh-updated');if(up2)up2.textContent=ghSel.branch?'· '+ghSel.branch:'';}catch{}}
document.addEventListener('click',e=>{if(!e.target.closest||(!e.target.closest('.csel')&&!e.target.closest('.cdrop')))hideCsel();});
window.addEventListener('scroll',()=>{hideCsel();},true);
function ghCommitUser(){const v=$('#gh-user-input').value.trim();if(v&&v!==ghUser){ghUser=v;store.set('gh',ghUser);ghSel={repo:'',branch:'',defBranch:''};store.set('ghSel',ghSel);}ghSyncInputs();loadGH();}
$('#gh-user-input').addEventListener('keydown',e=>{if(e.key==='Enter')ghCommitUser();});
$('#gh-user-input').addEventListener('blur',ghCommitUser);
$('#gh-open').onclick=()=>{if(ghUser)window.open('https://github.com/'+encodeURIComponent(ghUser),'_blank');};
$('#gh-refresh').onclick=()=>{store.set('ghCache',null);loadGH();};
$('#gh-save2').onclick=()=>{const v=$('#gh-input').value.trim();if(v)ghUser=v;store.set('gh',ghUser);store.set('ghToken',$('#gh-token').value.trim());ghSyncInputs();loadGH();};
function ghHeaders(){const h={};const t=store.get('ghToken','');if(t)h.Authorization='token '+t;return h;}
function mdToText(md){return String(md||'').replace(/```[\s\S]*?```/g,' ').replace(/!\[([^\]]*)\]\([^)]*\)/g,'$1').replace(/\[([^\]]*)\]\([^)]*\)/g,'$1').replace(/<[^>]+>/g,' ').replace(/^#{1,6}\s+/gm,'').replace(/(\*\*|__)(.*?)\1/g,'$2').replace(/(^|\W)\*([^*\n]+)\*/g,'$1$2').replace(/`([^`]+)`/g,'$1').replace(/^(\s*)[-*+]\s+/gm,'$1• ').replace(/^\s*\|.*$/gm,' ').replace(/[ \t]+/g,' ').replace(/\n{3,}/g,'\n\n').trim();}
async function loadGhReadme(){const sec=$('#gh-notif-sec'),box=$('#gh-readme');if(!sec||!box)return;if(!ghSel.repo){sec.classList.add('hidden');return;}try{const r=await fetch(`https://api.github.com/repos/${ghSel.repo}/readme`,{headers:Object.assign({Accept:'application/vnd.github.raw'},ghHeaders())});if(r.status===404){box.textContent='No README found';sec.classList.remove('hidden');return;}if(!r.ok)throw 0;const md=await r.text();box.textContent=mdToText(md).slice(0,1500);sec.classList.remove('hidden');}catch{sec.classList.add('hidden');}}
function syncTfSeg(){[...document.querySelectorAll('#tf-seg button')].forEach(b=>b.classList.toggle('on',b.dataset.tf===store.get('timeFormat','12h')));}
$$('#tf-seg button').forEach(b=>b.onclick=()=>{store.set('timeFormat',b.dataset.tf);syncTfSeg();tick();});
function shade(hex,f){let h=String(hex).replace('#','');if(h.length===3)h=h.split('').map(c=>c+c).join('');const n=parseInt(h,16)||0;const r=Math.round(((n>>16)&255)*f),g=Math.round(((n>>8)&255)*f),b=Math.round((n&255)*f);return `rgb(${r},${g},${b})`;}
async function loadGhLife(){const box=$('#gh-life');if(!box)return;const t=store.get('ghToken','');if(!t||!ghUser){box.classList.add('hidden');return;}try{let cal=null;const c=store.get('ghLife',null);if(c&&c.user===ghUser&&(Date.now()-c.ts)<864e5)cal=c.cal;else{const r=await fetch('https://api.github.com/graphql',{method:'POST',headers:{Authorization:'bearer '+t,'Content-Type':'application/json'},body:JSON.stringify({query:'query($login:String!){user(login:$login){contributionsCollection{contributionCalendar{totalContributions weeks{contributionDays{contributionCount date}}}}}}',variables:{login:ghUser}})});if(!r.ok)throw 0;const j=await r.json();cal=j.data&&j.data.user&&j.data.user.contributionsCollection&&j.data.user.contributionsCollection.contributionCalendar;if(!cal)throw 0;try{store.set('ghLife',{user:ghUser,ts:Date.now(),cal});}catch{}}const days=[];cal.weeks.forEach(w=>w.contributionDays.forEach(d=>days.push(d)));const total=cal.totalContributions||0;const todayK=new Date().toISOString().slice(0,10);let streak=0;for(let i=days.length-1;i>=0;i--){if(days[i].contributionCount>0)streak++;else{if(days[i].date>=todayK)continue;break;}}$('#gh-life-total').textContent=Number(total).toLocaleString();$('#gh-life-streak').textContent=streak;box.classList.remove('hidden');}catch{box.classList.add('hidden');}}
