async function loadGhLangBytes(){const cached=store.get('ghLangs',null);if(cached&&cached.user===ghUser&&(Date.now()-cached.ts)<864e5&&cached.map)return cached.map;const map={};await Promise.all(ghReposCache.map(async x=>{try{const r=await fetch(`https://api.github.com/repos/${x.full_name}/languages`,{headers:ghHeaders()});if(!r.ok)throw 0;const j=await r.json();Object.entries(j).forEach(([l,b])=>{map[l]=(map[l]||0)+b;});}catch{}}));if(!Object.keys(map).length)throw 0;try{store.set('ghLangs',{user:ghUser,ts:Date.now(),map});}catch{}return map;}
async function loadGhRepoLangs(repo){const c=store.get('ghLangRepo',null);if(c&&c.repo===repo&&(Date.now()-c.ts)<864e5&&c.map)return c.map;const r=await fetch(`https://api.github.com/repos/${repo}/languages`,{headers:ghHeaders()});if(!r.ok)throw 0;const j=await r.json();if(!Object.keys(j).length)throw 0;try{store.set('ghLangRepo',{repo,ts:Date.now(),map:j});}catch{}return j;}
async function renderGhLangs(){const bar=$('#gh-langbar'),list=$('#gh-langlist');if(!bar||!list)return;const counts={},byLang={};ghReposCache.forEach(x=>{let l=x.language||'Other';if(!String(l).trim())l='Other';counts[l]=(counts[l]||0)+1;(byLang[l]=byLang[l]||[]).push(x.name);});let rows=null,tot=0;const cap=$('#gh-cap');try{let bytes=null;if(ghSel.repo){try{bytes=await loadGhRepoLangs(ghSel.repo);}catch{bytes=null;}if(cap)cap.textContent='languages · '+((ghSel.repo||'').split('/')[1]||ghSel.repo);if(!bytes||!Object.keys(bytes).length){bar.innerHTML='';list.innerHTML='<li style="opacity:.55;font-size:13px">No languages detected</li>';return;}}else{if(cap)cap.textContent='languages across public repos';bytes=await loadGhLangBytes();}rows=Object.entries(bytes).sort((a,b)=>b[1]-a[1]).slice(0,6);tot=Math.max(1,rows.reduce((a,[,b])=>a+b,0));}catch{rows=Object.entries(counts).filter(([l])=>l!=='Other').sort((a,b)=>b[1]-a[1]).slice(0,6);tot=Math.max(1,rows.reduce((a,[,b])=>a+b,0));}bar.innerHTML='';list.innerHTML='';if(!rows.length){list.innerHTML='<li style="opacity:.55;font-size:13px">No languages detected</li>';return;}const CX=150,CY=82,RR=64,RK=0.55,DD=16,NS='http://www.w3.org/2000/svg';
const svg=document.createElementNS(NS,'svg');svg.setAttribute('viewBox','0 0 300 190');svg.setAttribute('width','100%');svg.innerHTML=`<defs><filter id="pieBlur" x="-60%" y="-60%" width="220%" height="220%"><feGaussianBlur stdDeviation="7"/></filter></defs><ellipse cx="${CX}" cy="${CY+DD+12}" rx="${RR+8}" ry="17" fill="rgba(0,0,0,.4)" filter="url(#pieBlur)"/>`;
const slices=[];let ang=-Math.PI/2;
rows.forEach(([l,n])=>{const frac=n/tot,a0=ang,a1=ang+frac*Math.PI*2;ang=a1;slices.push({l,n,frac,a0,a1});});
const repoTip=l=>((byLang[l]||[]).join(', '));
const shade=(hex,f)=>{let h=String(hex).replace('#','');if(h.length===3)h=h.split('').map(c=>c+c).join('');const n=parseInt(h,16)||0;const r=Math.round(((n>>16)&255)*f),g=Math.round(((n>>8)&255)*f),b=Math.round((n&255)*f);return `rgb(${r},${g},${b})`;};
const RRY=(RR*RK).toFixed(1);
const drawSlice=s=>{const col=GH_LANG_COLORS[s.l]||'#8b949e';const large=(s.a1-s.a0)>Math.PI?1:0;const x0=CX+RR*Math.cos(s.a0),y0=CY+RR*RK*Math.sin(s.a0),x1=CX+RR*Math.cos(s.a1),y1=CY+RR*RK*Math.sin(s.a1);const w=document.createElementNS(NS,'path');w.setAttribute('d',`M ${x0.toFixed(1)} ${y0.toFixed(1)} A ${RR} ${RRY} 0 ${large} 1 ${x1.toFixed(1)} ${y1.toFixed(1)} L ${x1.toFixed(1)} ${(y1+DD).toFixed(1)} A ${RR} ${RRY} 0 ${large} 0 ${x0.toFixed(1)} ${(y0+DD).toFixed(1)} Z`);w.setAttribute('fill',shade(col,0.5));svg.appendChild(w);const p=document.createElementNS(NS,'path');p.setAttribute('d',`M ${CX} ${CY} L ${x0.toFixed(1)} ${y0.toFixed(1)} A ${RR} ${RRY} 0 ${large} 1 ${x1.toFixed(1)} ${y1.toFixed(1)} Z`);p.setAttribute('fill',col);const t=document.createElementNS(NS,'title');const rt=repoTip(s.l);t.textContent=`${s.l} — ${(s.frac*100).toFixed(0)}%`+(rt?` · ${rt}`:'');p.appendChild(t);svg.appendChild(p);};
if(slices.length===1){const col=GH_LANG_COLORS[slices[0].l]||'#8b949e';const eb=document.createElementNS(NS,'ellipse');eb.setAttribute('cx',CX);eb.setAttribute('cy',CY+DD);eb.setAttribute('rx',RR);eb.setAttribute('ry',RR*RK);eb.setAttribute('fill',shade(col,0.5));svg.appendChild(eb);const et=document.createElementNS(NS,'ellipse');et.setAttribute('cx',CX);et.setAttribute('cy',CY);et.setAttribute('rx',RR);et.setAttribute('ry',RR*RK);et.setAttribute('fill',col);const t=document.createElementNS(NS,'title');t.textContent=`${slices[0].l} — 100%`;et.appendChild(t);svg.appendChild(et);}else{[...slices].sort((a,b)=>Math.sin((a.a0+a.a1)/2)-Math.sin((b.a0+b.a1)/2)).forEach(drawSlice);}
bar.appendChild(svg);
const FS=9,GAP=13,TOP=12,BOT=150;const allLy=[CY+DD+29];
[[1],[-1]].forEach(([sgn])=>{const items=slices.filter(s=>sgn>0?Math.cos((s.a0+s.a1)/2)>=-0.08:Math.cos((s.a0+s.a1)/2)<-0.08).map(s=>({s,y:CY+RR*Math.sin((s.a0+s.a1)/2)}));items.sort((a,b)=>a.y-b.y);const ys=items.map(o=>o.y);for(let i=1;i<ys.length;i++)ys[i]=Math.max(ys[i],ys[i-1]+GAP);if(ys.length){const over=ys[ys.length-1]-BOT;if(over>0)for(let i=0;i<ys.length;i++)ys[i]-=over;if(ys[0]<TOP){const sh=TOP-ys[0];for(let i=0;i<ys.length;i++)ys[i]+=sh;}}items.forEach((o,i)=>{const mid=(o.s.a0+o.s.a1)/2;const ex=CX+RR*Math.cos(mid),ey=CY+RR*RK*Math.sin(mid);const ly=ys[i];allLy.push(ly);const lx=sgn>0?224:76,jx=sgn>0?218:82;const ln=document.createElementNS(NS,'line');ln.setAttribute('x1',ex.toFixed(1));ln.setAttribute('y1',ey.toFixed(1));ln.setAttribute('x2',jx);ln.setAttribute('y2',ly.toFixed(1));ln.setAttribute('stroke','rgba(255,255,255,.35)');ln.setAttribute('stroke-width','1');svg.appendChild(ln);const tx=document.createElementNS(NS,'text');tx.setAttribute('x',lx);tx.setAttribute('y',(ly+4).toFixed(1));tx.setAttribute('text-anchor',sgn>0?'start':'end');tx.setAttribute('font-size',FS);tx.setAttribute('fill','rgba(255,255,255,.75)');tx.textContent=o.s.l;svg.appendChild(tx);});});svg.setAttribute('viewBox',`0 0 300 ${Math.min(200,Math.max(...allLy)+10)}`);}
