function hideWxDrop(){const d=$('#wx-drop');if(d)d.classList.remove('open');}
function positionWxDrop(){const ul=$('#wx-drop'),inp=$('#wx-input');if(!ul||!inp)return;const r=inp.getBoundingClientRect();ul.style.left=r.left+'px';ul.style.top=(r.bottom+6)+'px';ul.style.width=r.width+'px';}
function renderWxDrop(){const ul=$('#wx-drop');if(!ul)return;const q=($('#wx-input').value||'').trim();ul.innerHTML='';ul.classList.remove('open');if(q.length<2)return;clearTimeout(wxDropTimer);wxDropTimer=setTimeout(async()=>{try{if(wxAbortDrop)wxAbortDrop.abort();wxAbortDrop=new AbortController();const items=[];const ql=q.toLowerCase();Object.entries(WX_KNOWN).forEach(([name,[lat,lon]])=>{if(name.startsWith(ql))items.push({name:name.charAt(0).toUpperCase()+name.slice(1),sub:`${lat}, ${lon}`,city:name,rank:0});else if(name.includes(ql))items.push({name:name.charAt(0).toUpperCase()+name.slice(1),sub:`${lat}, ${lon}`,city:name,rank:2});});const r=await fetch(`https://geocoding-api.open-meteo.com/v1/search?name=${encodeURIComponent(q)}&count=10`,{signal:wxAbortDrop.signal});const j=await r.json();(j.results||[]).forEach(x=>{if(items.some(i=>i.city===x.name))return;const nl=(x.name||'').toLowerCase();const rank=nl.startsWith(ql)?0:nl.includes(ql)?1:2;items.push({name:x.name,sub:[x.admin1,x.country].filter(Boolean).join(', '),city:x.name,rank});});items.sort((a,b)=>a.rank-b.rank);ul.innerHTML='';items.slice(0,8).forEach(it=>{const li=document.createElement('li');const nm=document.createElement('span');nm.textContent=it.name;const sm=document.createElement('small');sm.textContent=it.sub;li.appendChild(nm);li.appendChild(sm);li.onclick=()=>{wx.city=it.city;store.set('weather',wx);wxSync();wxCommitted=true;loadWeather();};ul.appendChild(li);});if(items.length){ul.classList.add('open');positionWxDrop();}}catch(e){if(e&&e.name==='AbortError')return;}},300);}
