async function loadAQI(lat,lon){try{let box=$('#wx-aqi');if(!box){box=document.createElement('div');box.id='wx-aqi';const det=$('#weather-detail');if(det&&det.parentNode)det.parentNode.insertBefore(box,det.nextSibling);else return;}const r=await fetch(`https://air-quality-api.open-meteo.com/v1/air-quality?latitude=${lat}&longitude=${lon}&hourly=pm2_5,pm10,carbon_monoxide,nitrogen_dioxide,sulphur_dioxide,ozone&past_days=1&timezone=auto`);const j=await r.json();const H=j.hourly||{};const avg24=k=>{const a=(H[k]||[]).filter(v=>v!=null).slice(-24);return a.length?a.reduce((x,y)=>x+y,0)/a.length:NaN;};const c={pm2_5:avg24('pm2_5'),pm10:avg24('pm10'),carbon_monoxide:avg24('carbon_monoxide'),nitrogen_dioxide:avg24('nitrogen_dioxide'),sulphur_dioxide:avg24('sulphur_dioxide'),ozone:avg24('ozone')};const cc=await aqCountry(lat,lon);const sc=aqScale(cc);const res=AQI_CALC[sc]({pm25:c.pm2_5,pm10:c.pm10,co:c.carbon_monoxide,no2:c.nitrogen_dioxide,so2:c.sulphur_dioxide,o3:c.ozone});if(!isFinite(res.n))return;box.innerHTML='';const dot=document.createElement('span');dot.className='aqi-dot';dot.style.background=res.color;const tx=document.createElement('span');tx.textContent=`Air ${Math.round(res.n)} · ${res.cat}`;const tag=document.createElement('small');tag.style.opacity='.45';tag.textContent=` ${res.sys}`;box.appendChild(dot);box.appendChild(tx);box.appendChild(tag);}catch{}}
function moonRaDec(dt){const rad=Math.PI/180,sin=Math.sin,cos=Math.cos,atan2=Math.atan2;const y=dt.getUTCFullYear(),mo=dt.getUTCMonth()+1,dd=dt.getUTCDate(),ut=dt.getUTCHours()+dt.getUTCMinutes()/60+dt.getUTCSeconds()/3600;const d=367*y-7*((y+(((mo+9)/12)|0))/4|0)+((275*mo/9)|0)+dd-730530+ut/24;const norm=x=>((x%360)+360)%360;const Ms=norm(356.0470+0.9856002585*d),Mm=norm(115.3654+13.0649929509*d),Nm=norm(125.1228-0.0529538085*d),w=norm(318.0634+0.1643573223*d);const Lm=norm(Nm+w+Mm),ws=norm(282.9404+4.70935e-5*d),Ls=norm(ws+Ms);const D=norm(Lm-Ls),F=norm(Lm-Nm);const s1=Math.sin.bind(Math),rad2=rad;const lon=Lm+1.274*s1((Mm-2*D)*rad2)+0.658*s1(2*D*rad2)-0.186*s1(Ms*rad2)-0.059*s1((2*Mm-2*D)*rad2)-0.057*s1((Mm-2*D+Ms)*rad2)+0.053*s1((Mm+2*D)*rad2)+0.046*s1((2*D-Ms)*rad2)+0.041*s1((Mm-Ms)*rad2)-0.031*s1((Mm+Ms)*rad2)-0.015*s1((2*F-2*D)*rad2)+0.011*s1((Mm-4*D)*rad2);const lat=-0.173*s1((F-2*D)*rad2)-0.055*s1((Mm-F-2*D)*rad2)-0.046*s1((Mm+F-2*D)*rad2)+0.033*s1((F+2*D)*rad2)+0.017*s1((2*Mm+F)*rad2);const e=23.4393-3.563e-7*d;const x=cos(lon*rad)*cos(lat*rad);const yy=sin(lon*rad)*cos(lat*rad);const z=sin(lat*rad);const xeq=x,yeq=yy*cos(e*rad)-z*sin(e*rad),zeq=yy*sin(e*rad)+z*cos(e*rad);return{ra:((atan2(yeq,xeq)/rad)+360)%360,dec:Math.asin(zeq/Math.max(1e-9,Math.sqrt(xeq*xeq+yeq*yeq+zeq*zeq)))/rad};}
function moonAlt(dt,lat,lon){const rad=Math.PI/180;const{ra,dec}=moonRaDec(dt);const JD=dt.getTime()/864e5+2440587.5;const T=(JD-2451545)/36525;let g=(280.46061837+360.98564736629*(JD-2451545)+0.000387933*T*T)%360;g=(g+360)%360;let H=(g+lon-ra)%360;if(H>180)H-=360;if(H<-180)H+=360;return Math.asin(Math.sin(dec*rad)*Math.sin(lat*rad)+Math.cos(dec*rad)*Math.cos(lat*rad)*Math.cos(H*rad))/rad;}
function renderSkyArc(j,loc){const box=$('#wx-sun'),lab=$('#wx-arc-label');if(!box)return;try{
    const rise=new Date(j.daily.sunrise[0]),set=new Date(j.daily.sunset[0]),now=new Date();
    if(now>rise&&now<set){
      const f=Math.min(1,Math.max(0,(now-rise)/(set-rise)));
      const sx=100-90*Math.cos(Math.PI*f),sy=100-90*Math.sin(Math.PI*f);
      box.innerHTML=`<svg viewBox="0 0 200 104" width="220"><path d="M10,100 A90,90 0 0 1 190,100" fill="none" stroke="rgba(255,255,255,.25)" stroke-dasharray="4 4"/><circle cx="${sx.toFixed(1)}" cy="${sy.toFixed(1)}" r="9" fill="#fbbf24"/></svg><div class="muted small">↑ ${wxFmtSun(j.daily.sunrise[0])} &nbsp; ↓ ${wxFmtSun(j.daily.sunset[0])}</div>`;
      if(lab)lab.textContent='Sunrise & sunset';
    }else{
      const off=j.utc_offset_seconds||0,lat=loc.lat,lon=loc.lon;
      const H0=0.125,step=10*60*1000,t0=Date.now();let prevA=moonAlt(new Date(t0-36*3600*1000),lat,lon),prevT=t0-36*3600*1000;const cross=[];
      for(let t=t0-36*3600*1000+step;t<=t0+48*3600*1000;t+=step){const a=moonAlt(new Date(t),lat,lon);if((prevA<H0&&a>=H0)||(prevA>=H0&&a<H0)){const rising=prevA<H0;let lo=prevT,hi=t;for(let k=0;k<14;k++){const mid=(lo+hi)/2,am=moonAlt(new Date(mid),lat,lon);if((am<H0)===rising)lo=mid;else hi=mid;}cross.push({t:(lo+hi)/2,up:rising});}prevA=a;prevT=t;}
      const ups=cross.filter(c=>c.up).map(c=>c.t),downs=cross.filter(c=>!c.up).map(c=>c.t);
      const upNow=moonAlt(new Date(t0),lat,lon)>=H0;let mrise=mset=0;
      if(upNow){mrise=Math.max(...ups.filter(t=>t<=t0));mset=Math.min(...downs.filter(t=>t>mrise));}
      else{mrise=Math.min(...ups.filter(t=>t>t0));mset=Math.min(...downs.filter(t=>t>mrise));}
      const fmt=t=>{if(!isFinite(t))return'–';const d=new Date(t+off*1000);const h=d.getUTCHours(),m=String(d.getUTCMinutes()).padStart(2,'0');return `${h%12||12}:${m}${h>=12?'p':'a'}`;};
      let dot='',note='';if(upNow&&isFinite(mrise)&&isFinite(mset)&&mset>mrise){const f=Math.min(1,Math.max(0,(t0-mrise)/(mset-mrise)));const sx=100-90*Math.cos(Math.PI*f),sy=100-90*Math.sin(Math.PI*f);const SYN=29.53058867,REF=Date.UTC(2000,0,6,18,14)/864e5;const mAge=(((t0/864e5-REF)%SYN)+SYN)%SYN;const mIll=(1-Math.cos(2*Math.PI*mAge/SYN))/2;const wax=mAge<SYN/2,cres=mIll<0.5;const mrx=(8*Math.abs(Math.cos(2*Math.PI*mAge/SYN))).toFixed(1);const oSw=wax?1:0,iSw=((wax&&cres)||(!wax&&!cres))?0:1;const X=sx.toFixed(1),Y=sy.toFixed(1);dot=`<circle cx="${X}" cy="${Y}" r="8" fill="rgba(232,230,223,.16)"/><mask id="mphase"><rect x="${(sx-8).toFixed(1)}" y="${(sy-8).toFixed(1)}" width="16" height="16" fill="black"/><path d="M ${X} ${(sy-8).toFixed(1)} A 8 8 0 0 ${oSw} ${X} ${(sy+8).toFixed(1)} A ${mrx} 8 0 0 ${iSw} ${X} ${(sy-8).toFixed(1)} Z" fill="white"/></mask><circle cx="${X}" cy="${Y}" r="8" fill="#e8e6df" mask="url(#mphase)"/>`;}
      else if(isFinite(mrise)&&mrise>t0){const mins=Math.round((mrise-t0)/60000);dot=`<circle cx="10" cy="100" r="8" fill="none" stroke="rgba(255,255,255,.4)" stroke-dasharray="3 3"/>`;note=`<div class="muted small">rises in ${Math.floor(mins/60)?Math.floor(mins/60)+'h ':''}${mins%60}m</div>`;}
      box.innerHTML=`<svg viewBox="0 0 200 104" width="150"><path d="M10,100 A90,90 0 0 1 190,100" fill="none" stroke="rgba(255,255,255,.25)" stroke-dasharray="4 4"/>${dot}</svg><div class="muted small">↑ ${fmt(mrise)} &nbsp; ↓ ${fmt(mset)}</div>${note}`;
      if(lab)lab.textContent='Moonrise & moonset';
    }
  }catch{}}
async function loadWeather(){if(wxAbort)wxAbort.abort();wxAbort=new AbortController();const sig=wxAbort.signal;try{const loc=await wxResolve(wx.city||'Thane');if(sig.aborted)return;const r=await fetch(`https://api.open-meteo.com/v1/forecast?latitude=${loc.lat}&longitude=${loc.lon}&current=temperature_2m,weather_code&hourly=temperature_2m,weather_code&daily=weather_code,temperature_2m_max,temperature_2m_min,sunrise,sunset&forecast_days=7&timezone=auto`,{signal:sig});const j=await r.json();const t=wxToU(j.current.temperature_2m),desc=wxDesc(j.current.weather_code);$('#w-weather').textContent=loc.name;$('#weather-big').textContent=`${t}°`;$('#weather-detail').textContent=`${desc} · H:${wxToU(j.daily.temperature_2m_max[0])}° L:${wxToU(j.daily.temperature_2m_min[0])}°`;const WX_SVG_H='<svg viewBox="0 0 24 24" width="40" height="40" fill="none" stroke="currentColor" stroke-width="1.5">';
const WX_ICONS={Clear:WX_SVG_H+'<circle cx="12" cy="12" r="4.5"/><path d="M12 2v2.5M12 19.5V22M2 12h2.5M19.5 12H22M4.9 4.9l1.8 1.8M17.3 17.3l1.8 1.8M19.1 4.9l-1.8 1.8M6.7 17.3l-1.8 1.8"/></svg>',Cloudy:WX_SVG_H+'<path d="M18 10h-1.3A8 8 0 1 0 9 20h9a5 5 0 0 0 0-10z"/></svg>',Foggy:WX_SVG_H+'<path d="M18 10h-1.3A8 8 0 1 0 9 20h9a5 5 0 0 0 0-10z"/></svg>',Rain:WX_SVG_H+'<path d="M17 9h-1.2A7 7 0 1 0 8 17h9a4.5 4.5 0 0 0 0-8z"/><path d="M8 19v2M12 20v2M16 19v2"/></svg>',Snow:WX_SVG_H+'<path d="M17 9h-1.2A7 7 0 1 0 8 17h9a4.5 4.5 0 0 0 0-8z"/><path d="M8 19v2M12 20v2M16 19v2"/></svg>',Storm:WX_SVG_H+'<path d="M17 9h-1.2A7 7 0 1 0 8 17h9a4.5 4.5 0 0 0 0-8z"/><path d="M13 18l-2.5 4H13l-1 2.5"/></svg>'};
$('#wx-icon').innerHTML=(desc==='Clear'&&wxIsNight(j))?WX_MOON:(WX_ICONS[desc]||WX_ICONS.Cloudy);$('#weather-err').classList.add('hidden');$('#wx-searchrow').classList.remove('err');if(wxCommitted){wxCommitted=false;$('#wx-input').value='';}hideWxDrop();loadAQI(loc.lat,loc.lon);const curP=String(j.current.time).slice(0,13);let si=j.hourly.time.findIndex(x=>String(x).slice(0,13)>=curP);if(si<0)si=0;const hh=$('#weather-hourly');hh.innerHTML='';for(let i=si;i<Math.min(si+8,j.hourly.time.length);i++){const d=document.createElement('div');const h=new Date(j.hourly.time[i]).getHours();d.innerHTML=`<b>${i===si?'Now':`${h%12||12}${h>=12?'p':'a'}`}</b><span>${wxToU(j.hourly.temperature_2m[i])}°</span>`;hh.appendChild(d);}renderSkyArc(j,loc);const dw=$('#wx-daily');dw.innerHTML='';for(let i=1;i<=5&&i<j.daily.time.length;i++){const d=document.createElement('div');const lbl=new Date(j.daily.time[i]+'T12:00:00').toLocaleDateString('en-US',{weekday:'short'});d.innerHTML=`<span>${lbl}</span><span>${wxDesc(j.daily.weather_code[i])}</span><span class="d-low">${wxToU(j.daily.temperature_2m_min[i])}° <span class="d-high">/ ${wxToU(j.daily.temperature_2m_max[i])}°</span></span>`;dw.appendChild(d);}}catch(e){if(e&&e.name==='AbortError')return;$('#weather-err').classList.remove('hidden');$('#wx-searchrow').classList.add('err');}}
function wxSync(){$('#wx-input').value=wx.city||'';$$('#wx-units button').forEach(b=>b.classList.toggle('on',(b.dataset.u==='f')===(wx.unit==='f')));const sl=$('#set-loc');if(sl)sl.value=wx.latLon||'';const su=$('#set-units');if(su)su.value=wx.unit||'c';}
wxSync();loadWeather();
function wxCommit(){const v=$('#wx-input').value.trim();if(!v||v===wx.city)return;wx.city=v;store.set('weather',wx);wxCommitted=true;loadWeather();}
$('#wx-input').addEventListener('keydown',e=>{if(e.key==='Enter')wxCommit();});
$('#wx-input').addEventListener('input',()=>renderWxDrop());
$$('#wx-units button').forEach(b=>b.onclick=()=>{wx.unit=b.dataset.u;store.set('weather',wx);wxSync();loadWeather();});
$('#set-loc').onchange=e=>{const v=e.target.value.trim();const m=v.match(/^(-?\d+\.?\d*)[,\s]+(-?\d+\.?\d*)$/);if(!m)return;wx.city=v;wx.latLon=v;store.set('weather',wx);wxSync();loadWeather();};
function wxSyncSettings(){[...document.querySelectorAll('#wx-mode-seg button')].forEach(b=>b.classList.toggle('on',b.dataset.m===(wx.mode||'city')));const c=$('#set-wx-city');if(c&&document.activeElement!==c)c.value=wx.city||'';const r=$('#wx-city-row');if(r)r.style.display=(wx.mode||'city')==='city'?'':'none';}
function wxCommitMode(mm){wx.mode=mm;store.set('weather',wx);wxSyncSettings();loadWeather();}
$$('#wx-mode-seg button').forEach(b=>b.onclick=()=>wxCommitMode(b.dataset.m));
$('#set-wx-city').onchange=e=>{const v=e.target.value.trim();if(!v)return;wx.city=v;wx.mode='city';store.set('weather',wx);wxSync();wxSyncSettings();loadWeather();};
wxSyncSettings();
$('#set-units').onchange=e=>{wx.unit=e.target.value;store.set('weather',wx);wxSync();loadWeather();};

