function tzOffset(tz){try{const now=new Date();const a=new Date(now.toLocaleString('en-US',{timeZone:tz}));const u=new Date(now.toLocaleString('en-US',{timeZone:'UTC'}));const r=Math.round((a-u)/36e5*4)/4;if(!r)return'UTC';const s=r<0?'−':'+';const h=Math.floor(Math.abs(r)),m=Math.round((Math.abs(r)-h)*60);return `UTC${s}${h}${m?':'+String(m).padStart(2,'0'):''}`;}catch{return'UTC';}}
function tzDial(tz){try{const p=new Intl.DateTimeFormat('en-US',{timeZone:tz,hour:'2-digit',minute:'2-digit',hour12:false}).formatToParts(new Date());const g=t=>parseInt((p.find(x=>x.type===t)||{}).value||'0',10);const hr=(g('hour')%12)*30+g('minute')*0.5,mn=g('minute')*6;return `<svg width="40" height="40" viewBox="0 0 40 40"><circle cx="20" cy="20" r="18" fill="rgba(255,255,255,.05)" stroke="rgba(255,255,255,.15)"/><line x1="20" y1="20" x2="20" y2="12" stroke="#fff" stroke-width="2" transform="rotate(${hr} 20 20)"/><line x1="20" y1="20" x2="20" y2="8" stroke="rgba(255,255,255,.7)" stroke-width="1.2" transform="rotate(${mn} 20 20)"/><circle cx="20" cy="20" r="1.6" fill="#fff"/></svg>`;}catch{return'';}}
function presetTime(tz){try{return new Date().toLocaleDateString('en-US',{timeZone:tz,weekday:'short'})+' '+tzTime(tz);}catch{return'--:--';}}
function tzOffsetMin(tz){try{const now=new Date();const a=new Date(now.toLocaleString('en-US',{timeZone:tz}));const u=new Date(now.toLocaleString('en-US',{timeZone:'UTC'}));return Math.round((a-u)/36e5*4)/4*60;}catch{return 0;}}
function positionClockDrop(){const ul=$('#clock-presets'),inp=$('#clock-input');if(!ul||!inp)return;const r=inp.getBoundingClientRect();ul.style.left=r.left+'px';ul.style.top=(r.bottom+6)+'px';ul.style.width=r.width+'px';}
document.addEventListener('click',e=>{const ul=$('#clock-presets');if(ul&&ul.classList.contains('open')&&!e.target.closest('#clock-searchwrap')&&!e.target.closest('#clock-presets')){const inp=$('#clock-input');if(inp)inp.value='';renderClockPresets();}});
window.addEventListener('resize',()=>{const ul=$('#clock-presets');if(ul&&ul.classList.contains('open'))positionClockDrop();});
window.addEventListener('scroll',()=>{const ul=$('#clock-presets');if(ul&&ul.classList.contains('open'))positionClockDrop();},true);
function renderClockPresets(){const q=($('#clock-input').value||'').trim().toLowerCase();const ul=$('#clock-presets');ul.innerHTML='';ul.classList.remove('open');if(!q)return;const matches=CLOCK_PRESETS.filter(([l,tz])=>!clocks.some(c=>c.tz===tz)&&(l.toLowerCase().includes(q)||tz.toLowerCase().includes(q))).sort((a,b)=>tzOffsetMin(a[1])-tzOffsetMin(b[1])).slice(0,30);matches.forEach(([l,tz])=>{const li=document.createElement('li');li.dataset.tz=tz;li.innerHTML=`<span>${l}<br><small class="muted">${tzOffset(tz)}</small></span><b class="tz-t" data-fmt="mini">${presetTime(tz)}</b>`;li.onclick=()=>{clocks.push({id:`${tz}-${Date.now()}`,label:l,tz});store.set('clocks',clocks);$('#clock-input').value='';renderClocks();};ul.appendChild(li);});if(matches.length){ul.classList.add('open');positionClockDrop();}}
function renderClocks(){$('#clock-list').innerHTML='';[...clocks].sort((a,b)=>tzOffsetMin(a.tz)-tzOffsetMin(b.tz)).forEach((c)=>{const li=document.createElement('li');li.dataset.tz=c.tz;li.innerHTML=`${tzDial(c.tz)}<span>${c.label}<br><small class="muted">${tzOffset(c.tz)}</small></span><b class="tz-t">${tzTime(c.tz,true)}</b> <button class="habit-del">✕</button>`;li.querySelector('button').onclick=()=>{clocks=clocks.filter(x=>x.id!==c.id);store.set('clocks',clocks);renderClocks();};$('#clock-list').appendChild(li);});if(!clocks.length)$('#clock-list').innerHTML='<li class="muted" style="background:none;justify-content:center;font-size:12px;opacity:.6">No clocks yet — tap a city above</li>';renderClockPresets();$('#w-world').textContent=clocks.length?(clocks.length===1?'1 clock':`${clocks.length} clocks`):'No clocks';}
setInterval(()=>{const cm=$('#clock-modal');const wm=$('#weather-modal');if(wm&&wm.classList.contains('hidden')){const wd=$('#wx-drop');if(wd)wd.classList.remove('open');}if(cm&&cm.classList.contains('hidden')){const ul=$('#clock-presets');if(ul)ul.classList.remove('open');}$$('#clock-list li .tz-t, #clock-presets li .tz-t').forEach(b=>{const li=b.closest('li');const tz=li&&li.dataset.tz;if(!tz)return;if(b.dataset.fmt==='mini')b.textContent=presetTime(tz);else b.textContent=tzTime(tz,true);});},1000);
$('#clock-input').oninput=renderClockPresets;
$('#clock-add').onclick=()=>{const v=$('#clock-input').value.trim();if(!v)return;const pre=CLOCK_PRESETS.find(([l,tz])=>l.toLowerCase()===v.toLowerCase()||tz.toLowerCase()===v.toLowerCase());try{new Intl.DateTimeFormat('en',{timeZone:pre?pre[1]:v});}catch{return;}clocks.push({id:`${pre?pre[1]:v}-${Date.now()}`,label:pre?pre[0]:v,tz:pre?pre[1]:v});store.set('clocks',clocks);$('#clock-input').value='';renderClocks();};
renderClocks();

// Notes (Suite: pin, search, edit, Ctrl+Enter)
let notes=store.get('notes',[]);
let noteEdit=null,noteQ='';
function renderNotes(){const q=noteQ.toLowerCase();const list=notes.filter(n=>((n.title||'')+' '+(n.body||'')).toLowerCase().includes(q)).sort((a,b)=>((b.pinned?1:0)-(a.pinned?1:0))||b.updatedAt-a.updatedAt);const ul=$('#notes-list');ul.innerHTML='';list.forEach(n=>{const li=document.createElement('li');li.className='note-card';const head=document.createElement('div');head.className='note-head';const t=document.createElement('div');t.className='note-title';t.textContent=noteTitleOf(n.title);const tools=document.createElement('div');tools.className='note-tools';const pin=document.createElement('button');pin.textContent='📌';if(n.pinned)pin.classList.add('pinned');pin.title=n.pinned?'Unpin':'Pin';pin.onclick=()=>{n.pinned=!n.pinned;store.set('notes',notes);renderNotes();};const del=document.createElement('button');del.textContent='✕';del.className='del';del.title='Delete';del.onclick=()=>{notes=notes.filter(x=>x.id!==n.id);store.set('notes',notes);renderNotes();};tools.appendChild(pin);tools.appendChild(del);head.appendChild(t);head.appendChild(tools);li.appendChild(head);if(n.body){const bl=n.body.split('\n');const rest=(bl[0]===n.title?bl.slice(1):bl).join('\n').replace(/^\n+/,'');if(rest){const b=document.createElement('div');b.className='note-body';b.innerHTML=mdRender(rest);li.appendChild(b);}}const ed=document.createElement('button');ed.className='note-edit';ed.textContent='Edit';ed.onclick=()=>{noteEdit=n.id;$('#notes-input').value=n.body;$('#notes-cancel').classList.remove('hidden');noteMode='edit';syncNoteMode();$('#notes-input').focus();};li.appendChild(ed);li.onclick=e=>{if(e.target.closest('button'))return;li.classList.toggle('open');};ul.appendChild(li);});$('#notes-count').textContent=`${list.length} note${list.length===1?'':'s'}`;$('#notes-empty').style.display=list.length?'none':'';const wn=$('#w-notes');if(wn)wn.textContent='Click to view';}
function noteTitleOf(v){return String(v||'').split('\n')[0].replace(/^#{1,3}\s+/,'').replace(/^\*\*(.+)\*\*$/,'$1').slice(0,40)||'Untitled';}
function saveNote(){const v=$('#notes-input').value;if(!v.trim()&&!noteEdit)return;const ts=Date.now();if(noteEdit){const n=notes.find(x=>x.id===noteEdit);if(n){n.body=v;n.title=noteTitleOf(v);n.updatedAt=ts;}}else{if(!v.trim())return;notes.unshift({id:String(ts),title:noteTitleOf(v),body:v,pinned:false,createdAt:ts,updatedAt:ts});}$('#notes-input').value='';noteEdit=null;$('#notes-cancel').classList.add('hidden');store.set('notes',notes);renderNotes();}
$('#notes-search').oninput=e=>{noteQ=e.target.value;renderNotes();};
let noteMode='edit';
const NM_ICONS={edit:'<svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/></svg>',preview:'<svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2"><path d="M17 3a2.8 2.8 0 1 1 4 4L7.5 20.5 2 22l1.5-5.5z"/></svg>'};
function syncNoteMode(){const mb=$('#note-mode-btn');if(mb){mb.innerHTML=NM_ICONS[noteMode];mb.title=noteMode==='edit'?'Preview':'Edit';}const ta=$('#notes-input'),pv=$('#note-preview'),tb=$('#note-toolsbar');const ed=noteMode==='edit';if(ta)ta.classList.toggle('hidden',!ed);if(pv){pv.classList.toggle('hidden',ed);if(!ed)pv.innerHTML=mdRender(ta?ta.value:'');}if(tb)[...tb.querySelectorAll('[data-fmt],[data-h],.nt-sep')].forEach(x=>x.style.display=ed?'':'none');}
$('#note-mode-btn').onclick=()=>{noteMode=noteMode==='edit'?'preview':'edit';syncNoteMode();};
$('#notes-input').addEventListener('input',()=>{if(noteMode==='preview'){const pv=$('#note-preview');if(pv)pv.innerHTML=mdRender($('#notes-input').value);}});
syncNoteMode();
function mdRender(t){const esc=String(t).replace(/&/g,'&amp;').replace(/</g,'&lt;');return esc.replace(/^### (.+)$/gm,'<div class="nh3">$1</div>').replace(/^## (.+)$/gm,'<div class="nh2">$1</div>').replace(/^# (.+)$/gm,'<div class="nh1">$1</div>').replace(/\*\*(.+?)\*\*/g,'<b>$1</b>').replace(/(^|\W)\*([^*\n]+)\*/g,'$1<i>$2</i>').replace(/^(\s*)-\s*\[\s\]\s+(.*)$/gm,'$1☐ $2').replace(/^(\s*)-\s*\[\s?[xX]\s*\]\s+(.*)$/gm,'$1☑ $2');}
function noteHeading(lv){const ta=$('#notes-input');if(!ta)return;const s=ta.selectionStart;const ls=ta.value.lastIndexOf('\n',s-1)+1;let le=ta.value.indexOf('\n',s);if(le<0)le=ta.value.length;const line=ta.value.slice(ls,le).replace(/^#{1,3}\s+/,'');const pre='#'.repeat(Math.min(3,Math.max(1,lv)))+' ';ta.value=ta.value.slice(0,ls)+pre+line+ta.value.slice(le);ta.focus();ta.setSelectionRange(ls+pre.length,ls+pre.length+line.length);}
function noteWrap(pre,post){const ta=$('#notes-input');if(!ta)return;const s=ta.selectionStart,e=ta.selectionEnd,v=ta.value;ta.value=v.slice(0,s)+pre+v.slice(s,e)+post+v.slice(e);ta.focus();ta.setSelectionRange(s+pre.length,e+pre.length);}
function noteBullets(kind){const ta=$('#notes-input');if(!ta)return;const s=ta.selectionStart;const ls=ta.value.lastIndexOf('\n',s-1)+1;let le=ta.value.indexOf('\n',s);if(le<0)le=ta.value.length;const out=ta.value.slice(ls,le).split('\n').map((ln,i)=>{const t=ln.replace(/^(\s*)(?:[-*]|\d+\.|-\s*\[\s?\])\s+/,'$1');if(kind==='num')return t.replace(/^(\s*)/,'$1'+(i+1)+'. ');if(kind==='task')return t.replace(/^(\s*)/,'$1- [ ] ');return t.replace(/^(\s*)/,'$1- ');});ta.value=ta.value.slice(0,ls)+out.join('\n')+ta.value.slice(le);ta.focus();}
$$('#note-toolsbar [data-fmt]').forEach(b=>b.onclick=()=>{const f=b.dataset.fmt;if(f==='bold')noteWrap('**','**');else if(f==='italic')noteWrap('*','*');else noteBullets(f==='num'?'num':f==='task'?'task':'dash');});
$$('#note-toolsbar [data-h]').forEach(b=>b.onclick=()=>noteHeading(+b.dataset.h));
$('#notes-add').onclick=saveNote;
$('#notes-cancel').onclick=()=>{noteEdit=null;$('#notes-input').value='';$('#notes-cancel').classList.add('hidden');};
$('#notes-input').addEventListener('keydown',e=>{if(e.key==='Enter'&&(e.metaKey||e.ctrlKey))saveNote();});
renderNotes();

// Calendar (Suite: 42-cell grid, year progress, coming-up, holidays)
let calCursor=new Date();calCursor.setDate(1);
function calOrdinal(n){return n+(n===1?'st':n===2?'nd':n===3?'rd':'th');}
function calIsoWeek(d){const t=new Date(Date.UTC(d.getFullYear(),d.getMonth(),d.getDate()));const day=(t.getUTCDay()+6)%7+1;t.setUTCDate(t.getUTCDate()-day+3);const first=new Date(Date.UTC(t.getUTCFullYear(),0,4));return 1+Math.round(((t-first)/864e5-3+((first.getUTCDay()+6)%7))/7);}
function calHolidays(country,year){const ind=/india/i.test(country||'');const out=[];if(ind){out.push([0,26,'Republic Day','🇮🇳'],[0,14,'Makar Sankranti','🪁'],[7,15,'Independence Day','🇮🇳'],[8,2,'Gandhi Jayanti','🕊️'],[11,25,'Christmas','🎄']);if(year===2026)out.push([1,26,'Maha Shivaratri','🕉️'],[2,14,'Holi','🎨'],[3,18,'Good Friday','⛪'],[4,12,'Buddha Purnima','🪷'],[6,9,'Raksha Bandhan','🎀'],[7,26,'Janmashtami','🦚'],[9,22,'Dussehra','🏹'],[9,20,'Dhanteras','🪙'],[10,22,'Diwali','🪔'],[10,24,'Bhai Dooj','🍬'],[10,5,'Guru Nanak Jayanti','🙏']);}else{out.push([0,1,"New Year's Day",'🎆'],[6,4,'Independence Day','🇺🇸'],[9,31,'Halloween','🎃'],[10,11,'Veterans Day','🎖️'],[11,25,'Christmas','🎄']);}return out.map(([m,d,name,icon])=>({m,d,name,icon:icon||'🎉'}));}
let calSel=null;
function renderSel(){const box=$('#cal-sel');if(!box)return;if(!calSel){box.classList.add('hidden');box.innerHTML='';return;}const y=calCursor.getFullYear();const H=calHolidays(($('#set-holiday')&&$('#set-holiday').value)||'India',y);const list=H.filter(h=>h.m===calSel.m&&h.d===calSel.d);if(!list.length){box.classList.add('hidden');box.innerHTML='';return;}const dt=new Date(y,calSel.m,calSel.d);box.classList.remove('hidden');box.innerHTML='';const t=document.createElement('div');t.className='sel-date';t.textContent=`${dt.toLocaleDateString('en-US',{month:'long',day:'numeric'})} · ${dt.toLocaleDateString('en-US',{weekday:'long'})}`;box.appendChild(t);list.forEach(h=>{const li=document.createElement('li');li.style.listStyle='none';const s=document.createElement('span');s.textContent=`${h.icon||'🎉'} ${h.name}`;li.appendChild(s);box.appendChild(li);});}
function renderCal(){const y=calCursor.getFullYear(),m=calCursor.getMonth();const today=new Date();const isCur=y===today.getFullYear()&&m===today.getMonth();$('#cal-title').innerHTML=`${calCursor.toLocaleString('en',{month:'long'})} <span>${y}</span>`;const start=new Date(y,0,1);const doy=Math.floor((today-start)/864e5)+1;const diy=((y%4===0&&y%100!==0)||y%400===0)?366:365;$('#cal-sub').textContent=`${today.toLocaleDateString('en-US',{weekday:'long'})} the ${calOrdinal(today.getDate())} · Week ${calIsoWeek(today)} · Day ${doy} · ${diy-doy} left`;{const dimM=new Date(y,m+1,0).getDate(),nowM=today.getMonth(),nowY=today.getFullYear();let frac;if(y<nowY||(y===nowY&&m<nowM))frac=1;else if(y===nowY&&m===nowM)frac=today.getDate()/dimM;else frac=0;$('#cal-progress i').style.width=(frac*100)+'%';}const dim=new Date(y,m+1,0).getDate(),first=new Date(y,m,1).getDay(),prevDim=new Date(y,m,0).getDate();const H=calHolidays($('#set-holiday')?$('#set-holiday').value:'India',y);const keys=new Set(H.map(h=>`${h.m}-${h.d}`));let h=['S','M','T','W','T','F','S'].map(d=>`<span class="wd">${d}</span>`).join('');const cells=[];for(let i=first-1;i>=0;i--)cells.push({d:prevDim-i,out:true,mm:(m+11)%12});for(let d=1;d<=dim;d++)cells.push({d,out:false,mm:m});let nd=1;while(cells.length<42)cells.push({d:nd++,out:true,mm:(m+1)%12});cells.forEach(c=>{const hol=keys.has(`${c.mm}-${c.d}`);const tod=!c.out&&isCur&&c.d===today.getDate();h+=`<span data-mm="${c.mm}" data-d="${c.d}" class="${c.out?'out':''}${tod?' today':''}${hol&&!tod?' hol':''}${(!c.out&&calSel&&calSel.m===c.mm&&calSel.d===c.d)?' sel':''}">${c.d}</span>`;});$('#cal-grid').innerHTML=h;const t0=new Date();t0.setHours(0,0,0,0);const isCurView=y===t0.getFullYear()&&m===t0.getMonth();const up=H.map(x=>({...x,dt:new Date(y,x.m,x.d)})).filter(x=>isCurView?x.dt>=t0:x.dt.getMonth()===m).sort((a,b)=>a.dt-b.dt).slice(0,isCurView?3:6);const ul=$('#cal-coming');ul.innerHTML=`<div class="cup-label">${isCurView?'Coming up':calCursor.toLocaleString('en',{month:'long'})+' holidays'}</div>`;if(!up.length)ul.innerHTML+='<li class="muted">Nothing coming up</li>';up.forEach(x=>{const diff=Math.round((x.dt-t0)/864e5);const li=document.createElement('li');const nm=document.createElement('span');nm.textContent=`${x.icon||'🎉'} ${x.name}`;const sm=document.createElement('small');const lbl=x.dt.toLocaleDateString('en-US',{month:'short',day:'numeric'});sm.textContent=`${lbl} · ${diff===0?'today':diff>0?`in ${diff} day${diff===1?'':'s'}`:`${-diff} day${diff===-1?'':'s'} ago`}`;li.appendChild(nm);li.appendChild(sm);ul.appendChild(li);});renderSel();}
$('#cal-prev').onclick=()=>{calCursor.setMonth(calCursor.getMonth()-1);calSel=null;renderCal();renderSel();};
$('#cal-next').onclick=()=>{calCursor.setMonth(calCursor.getMonth()+1);calSel=null;renderCal();renderSel();};
$('#cal-grid').onclick=e=>{const s=e.target.closest('span[data-d]');if(!s||s.classList.contains('out'))return;calSel={m:+s.dataset.mm,d:+s.dataset.d};renderCal();renderSel();};
renderCal();

// Dock (Suite: stored shortcuts, magnification, right-click edit, shortcuts modal)
function seedShortcuts(){return $$('#dock a.dock-btn').map((a,i)=>({id:String(Date.now()+i),name:a.dataset.name||`Link ${i+1}`,url:a.dataset.url||a.href,cls:(a.querySelector('.gicon')||{}).className?String(a.querySelector('.gicon').className).replace('gicon','').trim():''}));}
let shortcuts=store.get('shortcuts',null);
if(!Array.isArray(shortcuts)||!shortcuts.length){shortcuts=seedShortcuts();store.set('shortcuts',shortcuts);}
function favHost(u){try{return new URL(u).hostname;}catch{return'';}}
function dockIcon(s){const h=favHost(s.url);const img=h?`<img src="https://www.google.com/s2/favicons?domain=${h}&sz=64" alt="" onerror="this.remove()">`:'';const letter=s.cls==='gmail'?'M':s.cls==='yt'?'▶':s.cls==='gh'?'◍':s.cls==='x'?'𝕏':s.cls==='rd'?'●':s.cls==='li'?'in':(s.name||'?').trim().charAt(0).toUpperCase();return `<span class="gicon ${s.cls||'grid'}">${letter}</span>${img}`;}
function renderDock(){const dock=$('#dock');dock.querySelectorAll('a.dock-btn').forEach(a=>a.remove());shortcuts.slice(0,12).forEach(s=>{const a=document.createElement('a');a.href=s.url;a.className='dock-btn';a.dataset.name=s.name;a.dataset.url=s.url;a.dataset.id=s.id;a.target='_blank';a.rel='noopener';a.innerHTML=dockIcon(s);dock.insertBefore(a,$('#dock-grid'));bindDockBtn(a);});renderShortcutsList();}
function bindDockBtn(b){b.addEventListener('mouseenter',()=>{const t=$('#tooltip');t.textContent=b.dataset.name||'App';t.classList.remove('hidden');const p=$('#url-preview');if(b.dataset.url){p.textContent=b.dataset.url;p.classList.remove('hidden');}});b.addEventListener('mouseleave',()=>{$('#tooltip').classList.add('hidden');$('#url-preview').classList.add('hidden');});b.addEventListener('contextmenu',e=>{e.preventDefault();const s=shortcuts.find(x=>x.id===b.dataset.id);if(!s)return;const nn=prompt('Rename shortcut:',s.name);if(nn===null)return;if(nn.trim())s.name=nn.trim();const nu=prompt('URL (Cancel keeps, type DELETE to remove):',s.url);if(nu===null){store.set('shortcuts',shortcuts);renderDock();return;}if(nu.trim().toUpperCase()==='DELETE'){if(confirm(`Delete "${s.name}"?`))shortcuts=shortcuts.filter(x=>x.id!==s.id);}else if(nu.trim())s.url=nu.trim();store.set('shortcuts',shortcuts);renderDock();});}
let dockMagnet=null;
function dockScale(i){if(dockMagnet===null||!store.get('mag',1))return 1;const d=Math.abs(i-dockMagnet);if(d>=1.5)return 1;const t=1-d/1.5;return 1+0.5*t*t;}
function dockMagnify(e){if(!store.get('mag',1))return;if(e.target.closest&&e.target.closest('#dock-grid')){dockMagnet=null;dockReset();return;}const dock=$('#dock');const btns=[...dock.querySelectorAll('a.dock-btn')];if(!btns.length)return;const r0=btns[0].getBoundingClientRect(),r1=btns[btns.length-1].getBoundingClientRect();const pitch=btns.length>1?(r1.left-r0.left)/(btns.length-1):r0.width;dockMagnet=(e.clientX-(r0.left+r0.width/2))/pitch;btns.forEach((b,idx)=>{const k=dockScale(idx);b.style.transform=`scale(${k}) translateY(${-(k-1)*12}px)`;b.style.transformOrigin='bottom center';b.style.transition=dockMagnet===null?'transform .25s cubic-bezier(.2,.8,.2,1)':'transform .08s linear';b.style.zIndex=k>1.05?'2':'';const im=b.querySelector('img');if(im){im.style.width=20*k+'px';im.style.height=20*k+'px';}});}
function dockReset(){dockMagnet=null;$$('#dock a.dock-btn').forEach(b=>{b.style.transform='';b.style.zIndex='';b.style.transition='transform .25s cubic-bezier(.2,.8,.2,1)';const im=b.querySelector('img');if(im){im.style.width='';im.style.height='';}});}
function renderShortcutsList(){const ul=$('#shortcuts-list');if(!ul)return;ul.innerHTML='';shortcuts.forEach(s=>{const li=document.createElement('li');li.className='sc-tile';const h=favHost(s.url);li.innerHTML=`<button class="sc-x" title="Delete">✕</button>${h?`<img src="https://www.google.com/s2/favicons?domain=${h}&sz=64" alt="">`:''}<span></span>`;li.querySelector('span').textContent=s.name;const im=li.querySelector('img');if(im)im.addEventListener('error',()=>im.remove());li.onclick=()=>window.open(s.url,'_blank');li.querySelector('.sc-x').onclick=e=>{e.stopPropagation();if(confirm(`Delete "${s.name}"?`)){shortcuts=shortcuts.filter(x=>x.id!==s.id);store.set('shortcuts',shortcuts);renderDock();}};ul.appendChild(li);});}
