function renderDiscard(){const t=$('#disc-toggles');if(t){t.innerHTML='';t.appendChild(toggleRow('Enable Discard',disc.enabled,()=>{disc.enabled=disc.enabled?0:1;saveDisc();renderDiscard();}));}const s=$('#disc-sliders');if(s){s.innerHTML='';s.appendChild(sliderRow('Idle Minutes','Tabs inactive this long become eligible',1,120,1,disc.idle,v=>v+'m',v=>{disc.idle=v;saveDisc();}));s.appendChild(sliderRow('Grace Period',"Don't discard tabs newer than this",10,300,5,disc.grace,v=>v+'s',v=>{disc.grace=v;saveDisc();}));s.appendChild(sliderRow('Min Inactive Tabs','',1,20,1,disc.minTabs,v=>''+v,v=>{disc.minTabs=v;saveDisc();}));}const t2=$('#disc-toggles2');if(t2){t2.innerHTML='';[['neverActive','Never discard active tab'],['neverAudible','Never discard audible tab'],['neverPinned','Never discard pinned tab'],['neverForm','Never discard unsaved forms'],['memPressure','Memory pressure']].forEach(([k,label])=>{t2.appendChild(toggleRow(label,disc[k],()=>{disc[k]=disc[k]?0:1;saveDisc();renderDiscard();}));});if(disc.memPressure)t2.appendChild(sliderRow('Free-memory threshold','',5,50,1,disc.memThreshold,v=>v+'%',v=>{disc.memThreshold=v;saveDisc();}));}const w=$('#disc-wl');if(w&&w.value!==disc.whitelist)w.value=disc.whitelist;}
$$('#disc-presets button').forEach(b=>b.onclick=()=>{const p=b.dataset.p;if(p==='gentle')Object.assign(disc,{idle:30,minTabs:5,grace:120});else if(p==='balanced')Object.assign(disc,{idle:15,minTabs:3,grace:60});else Object.assign(disc,{idle:5,minTabs:1,grace:30});saveDisc();renderDiscard();});
