function renderDimmer(){const t=$('#dim-toggles');if(t){t.innerHTML='';t.appendChild(toggleRow('Enable Dimmer',dim.enabled,()=>{dim.enabled=dim.enabled?0:1;saveDim();renderDimmer();}));}const md=$('#dim-mode');if(md)[...md.querySelectorAll('button')].forEach(b=>b.classList.toggle('on',b.dataset.m===dim.mode));const cw=$('#dim-colors');if(cw){cw.innerHTML='';const row=document.createElement('div');row.className='swrow';DIM_COLORS.forEach(([id,hex])=>{const s=document.createElement('button');s.className='sw'+(dim.color===id?' on':'');s.style.background=hex;s.title=id;s.onclick=()=>{dim.color=id;saveDim();renderDimmer();};row.appendChild(s);});const cust=document.createElement('input');cust.type='color';cust.value=/^#/.test(dim.color)?dim.color:'#000000';cust.style.cssText='display:none';cust.onchange=()=>{dim.color=cust.value;saveDim();renderDimmer();};const cw2=document.createElement('button');cw2.className='sw';cw2.textContent='+';cw2.style.cssText='background:transparent;border:2px dashed rgba(255,255,255,.2);color:rgba(255,255,255,.4)';cw2.onclick=()=>cust.click();cw2.appendChild(cust);row.appendChild(cw2);cw.appendChild(row);}const s=$('#dim-sliders');if(s){s.innerHTML='';s.appendChild(sliderRow('Intensity','',0,100,1,dim.intensity,v=>v+'%',v=>{dim.intensity=v;saveDim();}));}const t2=$('#dim-toggles2');if(t2){t2.innerHTML='';[['blur','Blur'],['white','Whitescreen protection'],['dark','Dark mode']].forEach(([k,label])=>{t2.appendChild(toggleRow(label,dim[k],()=>{dim[k]=dim[k]?0:1;saveDim();renderDimmer();}));});}const sc=$('#dim-sched');if(sc){sc.innerHTML='';sc.appendChild(toggleRow('Schedule',dim.sched,()=>{dim.sched=dim.sched?0:1;saveDim();renderDimmer();}));if(dim.sched){sc.appendChild(sliderRow('Start hour','',0,23,1,dim.startH,v=>v+'h',v=>{dim.startH=v;saveDim();}));sc.appendChild(sliderRow('End hour','',0,23,1,dim.endH,v=>v+'h',v=>{dim.endH=v;saveDim();}));}}}
function renderDimSites(){const ul=$('#dim-sites');if(!ul)return;ul.innerHTML='';Object.keys(dimSites).forEach(host=>{const li=document.createElement('li');const nm=document.createElement('span');nm.textContent=host;const del=document.createElement('button');del.textContent='✕';del.onclick=()=>{delete dimSites[host];saveDim();renderDimSites();};li.appendChild(nm);li.appendChild(del);ul.appendChild(li);});}
$('#dim-site-add').onclick=()=>{const v=$('#dim-site-input').value.trim();if(!v)return;dimSites[v]={enabled:true};$('#dim-site-input').value='';saveDim();renderDimSites();};
$$('#dim-presets button').forEach(b=>b.onclick=()=>{const p=b.dataset.p;if(p==='night')Object.assign(dim,{intensity:55,color:'black',blur:0});else if(p==='reading')Object.assign(dim,{intensity:25,color:'brown',blur:0});else Object.assign(dim,{intensity:70,color:'black',blur:0,mode:'media-only'});saveDim();renderDimmer();});
$$('#dim-mode button').forEach(b=>b.onclick=()=>{dim.mode=b.dataset.m;saveDim();renderDimmer();});
let yt=Object.assign({enabled:0,remember:1,shortcut:1},store.get('ytCfg',{}));
function renderYT(){const t=$('#yt-toggles');if(!t)return;t.innerHTML='';t.appendChild(toggleRow('Enable YT Fullscreen',yt.enabled,()=>{yt.enabled=yt.enabled?0:1;store.set('ytCfg',yt);renderYT();}));t.appendChild(toggleRow('Remember per video',yt.remember,()=>{yt.remember=yt.remember?0:1;store.set('ytCfg',yt);renderYT();}));t.appendChild(toggleRow('Keyboard shortcut',yt.shortcut,()=>{yt.shortcut=yt.shortcut?0:1;store.set('ytCfg',yt);renderYT();}));}
renderDiscard();renderDimmer();renderDimSites();renderYT();
// Command palette (Suite: sections, keyboard nav, engine fallback)

const DEFAULT_AGENTS=[['ChatGPT','https://chat.openai.com'],['Gemini','https://gemini.google.com'],['Claude','https://claude.ai'],['DeepSeek','https://deepseek.com'],['Grok','https://grok.com'],['Copilot','https://copilot.microsoft.com'],['Perplexity','https://perplexity.ai']];
let agents=store.get('agents',null);
if(!Array.isArray(agents)||!agents.length){agents=DEFAULT_AGENTS.map(([name,url],i)=>({id:String(Date.now()+i),name,url}));store.set('agents',agents);}

/* orbit defaults: two staggered columns flowing down-right (see renderOrbit) */
function renderOrbit(){const o=$('#ai-orbit');if(!o)return;o.innerHTML='';const n=agents.length;let orbOver=store.get('orbit2',{});
function attachOrbitDrag(el,a){el.style.touchAction='none';el.addEventListener('pointerdown',e=>{if(e.button!==undefined&&e.button!==0)return;e.preventDefault();try{el.setPointerCapture(e.pointerId);}catch{}const cs=getComputedStyle(el);const cur=el.style;const base=[parseFloat(cur.getPropertyValue('--tx'))||0,parseFloat(cur.getPropertyValue('--ty'))||0];const ox=e.clientX,oy=e.clientY;let moved=false;const move=ev=>{const dx=ev.clientX-ox,dy=ev.clientY-oy;if(!moved&&Math.hypot(dx,dy)>9){moved=true;el.classList.add('dragging');}if(moved){el.style.setProperty('--tx',(base[0]+dx).toFixed(1)+'px');el.style.setProperty('--ty',(base[1]+dy).toFixed(1)+'px');}};const up=ev=>{el.removeEventListener('pointermove',move);el.removeEventListener('pointerup',up);el.removeEventListener('pointercancel',up);el.classList.remove('dragging');if(moved){const nx=parseFloat(el.style.getPropertyValue('--tx')),ny=parseFloat(el.style.getPropertyValue('--ty'));orbOver[a.id]=[+nx.toFixed(1),+ny.toFixed(1)];store.set('orbit2',orbOver);el.addEventListener('click',ev2=>{ev2.stopPropagation();ev2.preventDefault();},{capture:true,once:true});}};el.addEventListener('pointermove',move);el.addEventListener('pointerup',up);el.addEventListener('pointercancel',up);});}
const make=(a,ts,gi)=>{const ov=orbOver[a.id];const p=ov||ts;const el=document.createElement('a');el.className='orbit-btn';el.href=a.url;el.target='_blank';el.rel='noopener';el.title=a.name;el.dataset.aid=a.id;el.style.cssText=`--tx:${(+p[0]).toFixed(1)}px;--ty:${(+p[1]).toFixed(1)}px;transition-delay:${30+gi*45}ms`;const h=favHost(a.url);el.innerHTML=`<span class="olet">${(a.name||'?').trim().charAt(0).toUpperCase()}</span>${h?`<img src="https://www.google.com/s2/favicons?domain=${h}&sz=64" alt="" onerror="this.remove()">`:''}`;attachOrbitDrag(el,a);o.appendChild(el);};let gi=0;const og=Object.assign({r:135,size:45,gap:55},store.get('orbitGeom',{}));const oel=$('#ai-orbit');if(oel)oel.style.setProperty('--os',og.size+'px');const R=og.r,r1=Math.max(60,R-(+og.gap||55)),A0=2,A1=92,na=Math.floor(n/2),nb=n-na;const spread=(r,k,off)=>{const p=[];for(let i=0;i<k;i++){const ang=(A0+(A1-A0)*(k===1?0.5:(i+off)/(k-(off?0:1))))*Math.PI/180;p.push([r*Math.cos(ang),r*Math.sin(ang)]);}return p;};const ptsA=spread(r1,na,0),ptsB=spread(R,nb,0.5);agents.slice(0,na).forEach((a,i)=>make(a,ptsA[i],gi++));agents.slice(na).forEach((a,i)=>make(a,ptsB[i],gi++));console.log('[aurora-orbit]',JSON.stringify({a:ptsA.map(p=>p.map(v=>+v.toFixed(1))),b:ptsB.map(p=>p.map(v=>+v.toFixed(1)))}));}
function renderOrbitGeom(){const g=$('#orbit-geom');if(!g)return;g.innerHTML='';if(store.get('geomV',0)!==3){store.set('geomV',3);store.set('orbitGeom',{r:135,size:45,gap:55});}const og=Object.assign({r:135,size:45,gap:55},store.get('orbitGeom',{}));const save=()=>{store.set('orbitGeom',og);renderOrbit();};g.appendChild(sliderRow('Fan radius','How far the arc reaches from the button',120,240,5,og.r,v=>v+'px',v=>{og.r=v;save();}));g.appendChild(sliderRow('Orb size','Diameter of the satellite buttons',36,60,2,og.size,v=>v+'px',v=>{og.size=v;save();}));g.appendChild(sliderRow('Row distance','Gap in pixels between the two rows',50,110,1,og.gap,v=>v+'px',v=>{og.gap=v;save();}));}
renderOrbitGeom();
function renderAgentsList(){const ul=$('#agents-list');if(!ul)return;ul.innerHTML='';agents.forEach(a=>{const li=document.createElement('li');const nm=document.createElement('span');nm.textContent=a.name;const sm=document.createElement('small');sm.textContent=a.url;const del=document.createElement('button');del.textContent='✕';del.title='Delete';del.onclick=()=>{agents=agents.filter(x=>x.id!==a.id);store.set('agents',agents);renderAgentsList();renderOrbit();};li.appendChild(nm);li.appendChild(sm);li.appendChild(del);ul.appendChild(li);});}
$('#agent-add').onclick=()=>{const n=$('#agent-name').value.trim(),u=$('#agent-url').value.trim();if(!n||!u)return;agents.push({id:String(Date.now()),name:n,url:/^https?:\/\//.test(u)?u:'https://'+u});$('#agent-name').value='';$('#agent-url').value='';store.set('agents',agents);renderAgentsList();renderOrbit();};
$('#orbit-reset').onclick=()=>{orbOver={};store.set('orbit2',orbOver);store.set('orbitGeom',{r:135,size:45,gap:55});renderOrbit();renderOrbitGeom();};
renderOrbit();renderAgentsList();







// AI bar + panel + zen + google apps + ui buttons + misc settings sync
function setAiBar(open){$('#ai-orbit')?.classList.toggle('open',!!open);$('#ai-agents-btn')?.classList.toggle('open',!!open);store.set('aiBar',open?1:0);}
$('#ai-agents-btn').onclick=e=>{e.stopPropagation();setAiBar(!$('#ai-orbit')?.classList.contains('open'));};
$('#ai-agents-btn').onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();$('#ai-agents-btn').click();}};
document.addEventListener('click',e=>{const w=$('#ai-orbit-wrap');if(w&&!w.contains(e.target))setAiBar(false);});
document.addEventListener('keydown',e=>{if(e.key==='Escape')setAiBar(false);});
if(store.get('aiBar',0))setAiBar(true);

$('#google-apps-btn').onclick=e=>{e.stopPropagation();$('#gapps-panel').classList.toggle('hidden');};
document.addEventListener('click',e=>{const p=$('#gapps-panel');if(p&&!p.classList.contains('hidden')&&!p.contains(e.target)&&e.target.id!=='google-apps-btn')p.classList.add('hidden');});

$('#fs-btn').onclick=()=>{if(document.fullscreenElement)document.exitFullscreen().catch(()=>{});else document.documentElement.requestFullscreen().catch(()=>{});};
function applyUiBtns(){$('#google-apps-btn').classList.toggle('hidden',!store.get('ui_gapps',1));$('#fs-btn').classList.toggle('hidden',!store.get('ui_fs',0));}
try{const _rt=renderToggles;renderToggles=function(){_rt();applyUiBtns();};}catch{}
applyUiBtns();

const _sh=$('#set-holiday');if(_sh){_sh.value=store.get('holiday','India');_sh.onchange=e=>{store.set('holiday',e.target.value);renderCal();};}
